/bin/bash -lc "python3 - <<'PY'
import os,json,subprocess
print('PUBLIC_ROOT_NAMES',os.listdir('/workspace'))
refs=['memory://agent-r0024','memory://agent-r0016','paper:din','paper:dmr','paper-seed-registry','industry/sources.json']
for i,ref in enumerate(refs):
 r=subprocess.run(['python3','/workspace/tools.py','resolve',ref],capture_output=True,text=True)
 p='/tmp/research-ref-'+str(i)+'.json';open(p,'w').write(r.stdout)
 try:
  d=json.loads(r.stdout)
  print(ref,'saved',p,'keys',list(d))
 except Exception: print(ref,'FAILED',r.stdout[:300],r.stderr[:200])
c=json.load(open('/tmp/r001-runtime.json'))['context']
receipts=[]
for ref in c['allowed_observation_ids']:
 r=subprocess.run(['python3','/workspace/tools.py','resolve','trial://'+ref],capture_output=True,text=True)
 try: receipts.append(json.loads(r.stdout))
 except Exception: print('FAIL',ref,r.stdout[:200])
json.dump(receipts,open('/tmp/r001-receipts.json','w'))
print('RECEIPTS',len(receipts),'KEYS',list(receipts[-1]))
PY"

